SELECT (SELECT COUNT(*) FROM candidates) AS expected_candidate_masters,(SELECT COUNT(*) FROM candidates c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id=c.target_id) AS candidate_masters_moved,(SELECT COUNT(*) FROM candidates c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM targets t JOIN albums a ON a.id=t.target_id) AS target_album_rows,(SELECT COUNT(*) FROM targets t WHERE (SELECT COUNT(*) FROM song_masters sm WHERE sm.album_id=t.target_id)=t.expected_count) AS targets_at_expected_size,(SELECT COUNT(*) FROM song_masters sm WHERE sm.album_id='pending-uploads') AS live_pending_master_count;
